use std::env;
use std::io::Write;

mod commands;
mod options;
mod output;

fn main() {
    let args: Vec<String> = env::args().collect();
    let executable_path = &args[0];
    let exe_name = std::path::Path::new(executable_path)
        .file_name()
        .and_then(|n| n.to_str())
        .unwrap_or("executable");

    let mut global_quiet = false;
    let mut global_version = false;
    let mut global_copyright = false;
    let mut global_help = false;
    let mut command_name = String::new();
    let mut cmd_args = Vec::new();

    let mut i = 1;
    let mut found_command = false;

    // Parse global options and find command
    while i < args.len() {
        let arg = &args[i];

        if arg.starts_with('-') && !found_command {
            match arg.as_str() {
                "-quiet" | "-noquiet" => {
                    global_quiet = arg == "-noquiet";
                }
                "-version" => {
                    global_version = true;
                }
                "-nversion" => {
                    global_version = false;
                }
                "-copyright" | "-nocopyrights" => {
                    global_copyright = arg == "-copyright";
                }
                "-h" | "-noh" => {
                    global_help = arg == "-h";
                }
                "-nice" => {
                    i += 1;
                    if i >= args.len() {
                        print_header(exe_name, "gmx", global_quiet);
                        eprintln!("-------------------------------------------------------");
                        eprintln!("Program:     {}, version 2027.0-dev-20260414-24ac8ab-unknown", exe_name);
                        eprintln!("Source file: src/gromacs/commandline/cmdlineparser.cpp (line 271)");
                        eprintln!("Function:    void gmx::CommandLineParser::parse(int*, char**)");
                        eprintln!();
                        eprintln!("Error in user input:");
                        eprintln!("Invalid command-line options");
                        eprintln!("  In command-line option -nice");
                        eprintln!("    Too few (valid) values");
                        eprintln!();
                        eprintln!("For more information and tips for troubleshooting, please check the GROMACS");
                        eprintln!("website at https://manual.gromacs.org/current/user-guide/run-time-errors.html");
                        eprintln!("-------------------------------------------------------");
                        std::process::exit(1);
                    }
                }
                "-backup" | "-nobackup" => {
                    // Ignore backup option
                }
                _ => {
                    eprintln!("Unknown option: {}", arg);
                    std::process::exit(1);
                }
            }
            i += 1;
        } else if !found_command {
            command_name = arg.clone();
            found_command = true;
            i += 1;
            // Collect remaining args for the command
            while i < args.len() {
                cmd_args.push(args[i].clone());
                i += 1;
            }
        } else {
            i += 1;
        }
    }

    // Print header if not quiet
    if !global_quiet {
        print_header(exe_name, "gmx", global_quiet);
    }

    // Handle version flag
    if global_version {
        print_version();
        return;
    }

    // Handle copyright flag
    if global_copyright {
        print_copyright();
        return;
    }

    // Route to command
    if command_name.is_empty() {
        if global_help {
            print_main_help(exe_name, global_quiet);
        } else {
            print_main_help(exe_name, global_quiet);
        }
    } else {
        commands::handle_command(&command_name, &cmd_args, exe_name, global_quiet);
    }
}

fn print_header(exe_name: &str, cmd_name: &str, is_quiet: bool) {
    if is_quiet {
        return;
    }
    println!("       :-) GROMACS - {} {}, 2027.0-dev-20260414-24ac8ab-unknown (-:", cmd_name, exe_name);
    println!();
    println!("Executable:   /{}", exe_name);
    println!("Data prefix:  /usr/local/gromacs");
    println!("Working dir:  {}", env::current_dir()
        .map(|p| p.to_string_lossy().to_string())
        .unwrap_or_else(|_| "/workspace".to_string()));
    println!("Command line:");
    let args: Vec<String> = env::args().collect();
    print!("  {}", exe_name);
    for (i, arg) in args.iter().enumerate().skip(1) {
        print!(" {}", arg);
    }
    println!();
}

fn print_main_help(exe_name: &str, is_quiet: bool) {
    if !is_quiet {
        output::print_random_quote();
    }

    println!();
    println!("SYNOPSIS");
    println!();
    println!("gmx [-[no]h] [-[no]quiet] [-[no]version] [-[no]copyright] [-nice <int>]");
    println!("    [-[no]backup]");
    println!();
    println!("OPTIONS");
    println!();
    println!("Other options:");
    println!();
    println!(" -[no]h                     (no)");
    println!("           Print help and quit");
    println!(" -[no]quiet                 (no)");
    println!("           Do not print common startup info or quotes");
    println!(" -[no]version               (no)");
    println!("           Print extended version information and quit");
    println!(" -[no]copyright             (no)");
    println!("           Print copyright information on startup");
    println!(" -nice   <int>              (19)");
    println!("           Set the nicelevel (default depends on command)");
    println!(" -[no]backup                (yes)");
    println!("           Write backups if output files exist");
    println!();
    println!("Additional help is available on the following topics:");
    println!("    commands    List of available commands");
    println!("    selections  Selection syntax and usage");
    println!("To access the help, use 'gmx help <topic>'.");
    println!("For help on a command, use 'gmx help <command>'.");
}

