use std::env;

mod commands;
mod options;
mod output;

fn main() {
    let args: Vec<String> = env::args().collect();
    let executable_path = &args[0];
    let exe_name = if executable_path.contains('/') {
        std::path::Path::new(executable_path)
            .file_name()
            .and_then(|n| n.to_str())
            .unwrap_or("executable")
    } else {
        executable_path.as_str()
    };

    let mut global_quiet = false;
    let mut global_version = false;
    let mut global_copyright = false;
    let mut global_help = false;
    let mut command_name = String::new();
    let mut cmd_args = Vec::new();

    let mut i = 1;
    let mut found_command = false;

    // Parse global options and find command
    while i < args.len() {
        let arg = &args[i];

        if arg.starts_with('-') && !found_command {
            match arg.as_str() {
                "-quiet" | "-noquiet" => {
                    global_quiet = arg == "-noquiet";
                }
                "-version" => {
                    global_version = true;
                }
                "-nversion" => {
                    global_version = false;
                }
                "-copyright" | "-nocopyrights" => {
                    global_copyright = arg == "-copyright";
                }
                "-h" | "-noh" => {
                    global_help = arg == "-h";
                }
                "-nice" => {
                    i += 1;
                    if i >= args.len() {
                        print_header(&executable_path, "gmx", global_quiet);
                        eprintln!("-------------------------------------------------------");
                        eprintln!("Program:     executable, version 2027.0-dev-20260414-24ac8ab-unknown");
                        eprintln!("Source file: src/gromacs/commandline/cmdlineparser.cpp (line 271)");
                        eprintln!("Function:    void gmx::CommandLineParser::parse(int*, char**)");
                        eprintln!();
                        eprintln!("Error in user input:");
                        eprintln!("Invalid command-line options");
                        eprintln!("  In command-line option -nice");
                        eprintln!("    Too few (valid) values");
                        eprintln!();
                        eprintln!("For more information and tips for troubleshooting, please check the GROMACS");
                        eprintln!("website at https://manual.gromacs.org/current/user-guide/run-time-errors.html");
                        eprintln!("-------------------------------------------------------");
                        std::process::exit(1);
                    }
                }
                "-backup" | "-nobackup" => {
                    // Ignore backup option
                }
                _ => {
                    eprintln!("Unknown option: {}", arg);
                    std::process::exit(1);
                }
            }
            i += 1;
        } else if !found_command {
            command_name = arg.clone();
            found_command = true;
            i += 1;
            // Collect remaining args for the command
            while i < args.len() {
                cmd_args.push(args[i].clone());
                i += 1;
            }
        } else {
            i += 1;
        }
    }

    // Print header if not quiet
    if !global_quiet {
        print_header(&executable_path, "gmx", global_quiet);
    }

    // Handle version flag
    if global_version {
        print_version(&executable_path);
        return;
    }

    // Handle copyright flag
    if global_copyright {
        print_copyright(&executable_path);
        return;
    }

    // Route to command
    if command_name.is_empty() {
        if global_help {
            print_main_help(global_quiet);
        } else {
            print_main_help(global_quiet);
        }
    } else {
        commands::handle_command(&command_name, &cmd_args, &executable_path, global_quiet);
    }
}

