        println!("           Print extended version information and quit");
        println!(" -[no]copyright             (no)");
        println!("           Print copyright information on startup");
        println!(" -nice   <int>              (19)");
        println!("           Set the nicelevel (default depends on command)");
        println!(" -[no]backup                (yes)");
        println!("           Write backups if output files exist");
        println!();
        println!("Additional help is available on the following topics:");
        println!("    commands    List of available commands");
        println!("    selections  Selection syntax and usage");
        println!("To access the help, use 'gmx help <topic>'.");
        println!("For help on a command, use 'gmx help <command>'.");
    } else {
        let topic = &args[0];
        match topic.as_str() {
            "commands" => print_commands_list(),
            "selections" => print_selections_help(),
            "mdrun" => print_mdrun_help(),
            "grompp" => print_grompp_help(),
            "pdb2gmx" => print_pdb2gmx_help(),
            "analyze" => print_analyze_help(),
            _ => print_command_help(topic),
