        println!("Additional help is available on the following topics:");
        println!("    commands    List of available commands");
        println!("    selections  Selection syntax and usage");
        println!("To access the help, use 'gmx help <topic>'.");
        println!("For help on a command, use 'gmx help <command>'.");
    } else {
        let topic = &args[0];
        match topic.as_str() {
            "commands" => print_commands_list(),
            "selections" => print_selections_help(),
            "mdrun" => print_mdrun_help(),
            "grompp" => print_grompp_help(),
