    let args: Vec<String> = env::args().collect();
    let executable_path = &args[0];
    let exe_name = if executable_path.contains('/') {
        std::path::Path::new(executable_path)
            .file_name()
            .and_then(|n| n.to_str())
            .unwrap_or("executable")
    } else {
        executable_path.as_str()
    };

    let mut global_quiet = false;
    let mut global_version = false;
    let mut global_copyright = false;
    let mut global_help = false;
    let mut command_name = String::new();
    let mut cmd_args = Vec::new();

    let mut i = 1;
    let mut found_command = false;

    // Parse global options and find command
    while i < args.len() {
        let arg = &args[i];

        if arg.starts_with('-') && !found_command {
            match arg.as_str() {
                "-quiet" | "-noquiet" => {
                    global_quiet = arg == "-noquiet";
                }
                "-version" => {
                    global_version = true;
                }
                "-nversion" => {
                    global_version = false;
                }
                "-copyright" | "-nocopyrights" => {
                    global_copyright = arg == "-copyright";
                }
                "-h" | "-noh" => {
                    global_help = arg == "-h";
                }
                "-nice" => {
                    i += 1;
                    if i >= args.len() {
                        print_header(&executable_path, "gmx", global_quiet);
                        eprintln!("-------------------------------------------------------");
                        eprintln!("Program:     executable, version 2027.0-dev-20260414-24ac8ab-unknown");
                        eprintln!("Source file: src/gromacs/commandline/cmdlineparser.cpp (line 271)");
