                        eprintln!("For more information and tips for troubleshooting, please check the GROMACS");
                        eprintln!("website at https://manual.gromacs.org/current/user-guide/run-time-errors.html");
                        eprintln!("-------------------------------------------------------");
                        std::process::exit(1);
                    }
