use std::env;

mod commands;
mod options;
mod output;

fn main() {
    let args: Vec<String> = env::args().collect();
    let executable_path = &args[0];

    let mut global_quiet = false;
    let mut global_version = false;
    let mut global_copyright = false;
    let mut global_help = false;
    let mut command_name = String::new();
    let mut cmd_args = Vec::new();

    let mut i = 1;
    let mut found_command = false;

    // Parse global options and find command
    while i < args.len() {
        let arg = &args[i];

        if arg.starts_with('-') && !found_command {
            match arg.as_str() {
                "-quiet" => {
                    global_quiet = true;
                }
                "-noquiet" => {
                    global_quiet = false;
                }
                "-version" => {
                    global_version = true;
                }
                "-nversion" => {
                    global_version = false;
                }
                "-copyright" => {
                    global_copyright = true;
                }
                "-nocopyrights" => {
                    global_copyright = false;
                }
                "-h" => {
                    global_help = true;
                }
                "-noh" => {
                    global_help = false;
                }
                "-nice" => {
                    i += 1;
                    if i >= args.len() {
                        print_header(&executable_path, "gmx", global_quiet);
                        eprintln!("-------------------------------------------------------");
