    while i < args.len() {
        let arg = &args[i];

        if arg.starts_with('-') && !found_command {
            match arg.as_str() {
                "-quiet" => {
                    global_quiet = true;
                }
                "-noquiet" => {
                    global_quiet = false;
                }
