                    eprintln!("-------------------------------------------------------");
                    std::process::exit(1);
                }
            }
            i += 1;
        } else if !found_command {
            command_name = arg.clone();
            found_command = true;
            i += 1;
            // Collect remaining args for the command
            while i < args.len() {
                cmd_args.push(args[i].clone());
                i += 1;
            }
        } else {
            i += 1;
        }
    }

    // Print header if not quiet
    if !global_quiet && command_name != "help" {
        let cmd_header = if command_name.is_empty() { "gmx".to_string() } else { format!("gmx {}", command_name) };
        print_header(&executable_path, &cmd_header, global_quiet);
    } else if !global_quiet && command_name == "help" {
        print_help_header(&executable_path);
