use crate::output;

pub fn handle_command(command: &str, args: &[String], _exe_path: &str, _global_quiet: bool) {
    match command {
        "help" => handle_help(args, _exe_path),
        "grompp" => handle_grompp(args, _exe_path),
        "mdrun" => handle_mdrun(args, _exe_path),
        "pdb2gmx" => handle_pdb2gmx(args, _exe_path),
        "analyze" => handle_analyze(args, _exe_path),
        "anaeig" | "angle" | "awh" | "bar" | "bundle" | "check" | "chi" |
        "cluster" | "clustsize" | "confrms" | "convert-tpr" | "convert-trj" |
        "covar" | "current" | "density" | "densmap" | "densorder" | "dielectric" |
        "dipoles" | "disre" | "distance" | "dos" | "dssp" | "dump" | "dyecoupl" |
