        "helix" | "helixorient" | "hydorder" | "insert-molecules" | "lie" |
        "make_edi" | "make_ndx" | "mdmat" | "mindist" | "mk_angndx" | "msd" |
        "nmeig" | "nmens" | "nmr" | "nmtraj" | "nonbonded-benchmark" | "order" |
